function esc(v){return String(v??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));}

function validate(rows){const allowed=new Set(["food_drinks","groceries","dry_goods","bookshop","hardware","garments_clothes_footwear","jewelry","electronics_bcfe08f"]);if(!Array.isArray(rows)||rows.length>10000)throw Error("Invalid catalogue size");const seen=new Set();return rows.map(r=>{if(!r||typeof r.id!=="string"||!/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(r.id)||seen.has(r.id)||!allowed.has(r.category)||typeof r.name!=="string"||!r.name.trim()||r.name.length>250||typeof r.category_name!=="string"||!r.category_name.trim()||r.category_name.length>200||!["available","out_of_stock","check_live"].includes(r.availability)||![r.regular_price_kes,r.current_price_kes].every(p=>p===null||(typeof p==="number"&&Number.isFinite(p)&&p>0)))throw Error("Invalid catalogue row");seen.add(r.id);return {id:r.id,name:r.name,category:r.category,category_name:r.category_name,availability:r.availability,regular_price_kes:r.regular_price_kes,current_price_kes:r.current_price_kes};}).sort((a,b)=>a.id.localeCompare(b.id));}

function build(rows,origin,staging=false){if(origin!==(staging?"https://staging.invalid":"https://leogo.co.ke"))throw Error("Unexpected origin");rows=validate(rows);const files={};const root="/seo-catalogue/";const prod=r=>root+"products/"+r.id+"/";const cat=c=>root+"categories/"+c+"/";const groups=new Map();for(const r of rows){if(!groups.has(r.category))groups.set(r.category,[]);groups.get(r.category).push(r);}const page=(title,path,body,extra="")=>`<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(title)} | LEOGO Digital Market</title><meta name="description" content="${esc(title)} — browse approved listings on LEOGO Digital Market. Check current prices and availability in the marketplace."><link rel="canonical" href="${esc(origin+path)}">${staging?'<meta name="robots" content="noindex,nofollow">':''}<style>body{font:16px system-ui;max-width:880px;margin:0 auto;padding:24px;color:#07152f}header{border-bottom:3px solid #ff7800;padding:12px 0}a{color:#17549c}li{margin:12px 0}article{border:1px solid #ddd;border-radius:10px;padding:20px}footer{color:#555;margin-top:28px}</style></head><body><header><a href="${root}">LEOGO Digital Market — catalogue</a></header><main><h1>${esc(title)}</h1>${body}</main><footer>${staging?"Staging only. No purchases.":"<a href=\"/\">Visit LEOGO marketplace</a>"}</footer>${extra}</body></html>\n`;const put=(path,html)=>{files[path.slice(1)+"index.html"]=html;};const listing=rs=>"<ul>"+rs.map(r=>`<li><a href="${prod(r)}">${esc(r.name)}</a></li>`).join("")+"</ul>";put(root,page("Shop by category",root,"<p>Explore public LEOGO marketplace listings.</p><ul>"+[...groups].map(([c,rs])=>`<li><a href="${cat(c)}">${esc(rs[0].category_name)}</a> (${rs.length})</li>`).join("")+"</ul>"));for(const [c,rs] of groups)put(cat(c),page(rs[0].category_name,cat(c),listing(rs)));for(const r of rows){const shop=staging?"":`<p><a id="shop-link" hidden href="/?product_id=${encodeURIComponent(r.id)}&amp;product_category=${encodeURIComponent(r.category)}">View product and shop on LEOGO</a></p>`;put(prod(r),page(r.name,prod(r),`<article data-product-id="${r.id}"><p>Category: <a href="${cat(r.category)}">${esc(r.category_name)}</a></p><p id="live-status" role="status">Check current price and availability in the marketplace.</p>${shop}<p>Market Day, variant, delivery and final checkout prices are confirmed in the existing LEOGO shopping system.</p></article>`,staging?"":`<script src="${root}live.js" defer></script>`));}const paths=["/",root,...[...groups.keys()].map(cat),...rows.map(prod)];files["sitemap.xml"]='<?xml version="1.0" encoding="UTF-8"?>\n<!-- LEOGO SEO generator v2 -->\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n'+paths.map(p=>"  <url><loc>"+esc(origin+p)+"</loc></url>").join("\n")+"\n</urlset>\n";files["seo-catalogue/.generated"]="LEOGO SEO generator v2\n";return files;}

function liveSource(key){if(!/^sb_publishable_[A-Za-z0-9_-]+$/.test(key))throw Error("Expected existing public frontend key");return `(()=>{'use strict';const el=document.querySelector('[data-product-id]'),status=document.getElementById('live-status'),link=document.getElementById('shop-link');if(!el||!status||!link)return;const id=el.dataset.productId;const key=${JSON.stringify(key)};fetch('https://dzdciuqkqixwutvtfotj.supabase.co/rest/v1/rpc/seo_static_catalogue_v2',{method:'POST',headers:{apikey:key,'Content-Type':'application/json'},body:'{}',cache:'no-store'}).then(r=>{if(!r.ok)throw Error('unavailable');return r.json()}).then(rows=>{if(!Array.isArray(rows))throw Error('unavailable');const p=rows.find(x=>x.id===id);if(!p){status.textContent='This listing is no longer available.';el.querySelectorAll('a').forEach(a=>{a.hidden=true});document.querySelector('h1').textContent='Listing unavailable';document.title='Listing unavailable | LEOGO';const meta=document.createElement('meta');meta.name='robots';meta.content='noindex';document.head.append(meta);return;}const amount=typeof p.current_price_kes==='number'&&Number.isFinite(p.current_price_kes)&&p.current_price_kes>0?'KSh '+p.current_price_kes.toLocaleString('en-KE',{maximumFractionDigits:2}):'Select options to see price';const availability=p.availability==='available'?'Available':p.availability==='out_of_stock'?'Out of stock':'Check availability';status.textContent=amount+' · '+availability;link.href='/?product_id='+encodeURIComponent(p.id)+'&product_category='+encodeURIComponent(p.category);link.hidden=false;}).catch(()=>{status.textContent='Live price unavailable. Visit the marketplace to check current listings.';});})();\n`;}
export {validate,build,liveSource};
